// ZeroNote Android 权限插件 —— 构建脚本。
//
// 与 `tauri-plugin-statusbar` 同一条路（照抄它的结构）：
//   ① 按 COMMANDS 在 `permissions/autogenerated/` 生成权限文件
//      （`request_all_files_access` → `allow-request-all-files-access`）
//   ② `.android_path("android")` 让 Tauri CLI 自动把本插件的 Android 模块
//      include 进 `gen/android/tauri.settings.gradle` —— **不需要手改 gradle**。
const COMMANDS: &[&str] = &["request_all_files_access"];

fn main() {
  tauri_plugin::Builder::new(COMMANDS)
    .android_path("android")
    .build();
}
